"""Build the screenshot-first page from approved real captures and generic sections."""
import html
import re
from pathlib import Path
from PIL import Image
from build_followup import coverage_section

SITE = Path(__file__).resolve().parents[1]
old = (SITE / "index.html").read_text(encoding="utf-8")
head = old.split("<body>")[0]
head = re.sub(r"<title>.*?</title>", "<title>Real canvas app review · Power Platform Solution Reviewer</title>", head, flags=re.S)


def section(name):
    return re.search(r'<section\b[^>]*\bid="' + name + r'"[^>]*>.*?</section>', old, re.S).group()


def figure(name, alt, caption, eager=False):
    path = "examples/real-canvas/" + name
    with Image.open(SITE / path) as image:
        width, height = image.size
    loading = 'fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<figure class="screenshot"><a class="image-link" href="{path}" aria-label="Inspect full-size approved image: {html.escape(alt,quote=True)}"><img src="{path}" width="{width}" height="{height}" alt="{html.escape(alt,quote=True)}" {loading}></a><figcaption>{caption}</figcaption></figure>'


menu = figure("native-upload-menu-before-selection.png", "Actual native upload menu before selecting the real solution file; private navigation and identities masked.", "<strong>Native capture · before selection.</strong> The menu is open; this frame alone is not upload completion.", True)
uploaded = figure("native-upload-file-row-confirmed.png", "Actual confirmed uploaded file row for the matched real-canvas review; filename and identities privacy-masked.", "<strong>Native capture · uploaded row confirmed.</strong> This is the actual matched file row, not a generic historical folder example.", True)
main = figure("actual-result-review-txt.png", "Actual matched MAIN report opening showing a Partial real-canvas review, with private source and run identifiers masked.", "<strong>Native MAIN viewport.</strong> Partial is retained. This screenshot is an excerpt; the complete text and footer are available below.", True)
